func (c *pageCatalog) groupByParamDate(format string, order ...string) (PagesGroup, error) {
	if len(c.groupedPages) == 0 {
		return nil, nil
	}
	// Cache the dates.
	dates := make(map[Page]time.Time)

	sorter := func(pages Pages) Pages {
		var r Pages

		for _, p := range pages {
			param := resource.GetParam(p, c.groupKey)
			var t time.Time

			if param != nil {
				var ok bool
				if t, ok = param.(time.Time); !ok {
