			return dates[p1].Unix() < dates[p2].Unix()
		}
		pageBy(pdate).Sort(r)
		return r
	}
	getDate := func(p Page) time.Time {
		return dates[p]
	}
	return c.groupByDateField(format, sorter, getDate, order...)
}

